<span class="line"><span class="token keyword">const</span> shadow <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ShadowRealm</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
